import "server-only";
import { createHmac } from "node:crypto";
import type { Prisma } from "@/generated/prisma/client";
import { db } from "@/lib/db";

export function deletionSubjectHash(subject: string) {
  const key = process.env.DELETION_TOMBSTONE_HMAC_KEY;
  if (!key || !/^[a-f\d]{64}$/i.test(key))
    throw new Error(
      "DELETION_TOMBSTONE_HMAC_KEY must contain 64 hexadecimal characters.",
    );
  return createHmac("sha256", Buffer.from(key, "hex"))
    .update(`google:${subject}`)
    .digest("hex");
}
export async function hasDeletionTombstone(
  subject: string,
  tx?: Prisma.TransactionClient,
) {
  const job = await (tx ?? db).accountDeletionJob.findUnique({
    where: { googleSubjectHash: deletionSubjectHash(subject) },
    select: { completedAt: true },
  });
  return Boolean(job && !job.completedAt);
}
